CREATE TABLE IF NOT EXISTS market_impact_cost_log (
  log_id INTEGER PRIMARY KEY AUTOINCREMENT,
  ordersmark TEXT NOT NULL,
  mic NUMERIC NOT NULL,
  calculated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE PROCEDURE recalc_market_impact_cost()
BEGIN
  DECLARE v_mkteffect REAL;
  DECLARE v_dealcount REAL;
  DECLARE v_dealquote REAL;
  DECLARE v_mic REAL;
  DECLARE v_ordersmark TEXT;
  DECLARE done INT DEFAULT FALSE;

  DECLARE cur CURSOR FOR
    SELECT TRIM(o.recordvault), o.dealcount, o.dealquote
    FROM orders o
    WHERE o.orderflow = 'New';

  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;

  SELECT AVG(CAST(sm.mkteffect AS REAL)) INTO v_mkteffect
  FROM systemmonitoring sm;

  IF v_mkteffect IS NULL THEN
    SET v_mkteffect = 0;
  END IF;

  OPEN cur;

  read_loop: LOOP
    FETCH cur INTO v_ordersmark, v_dealcount, v_dealquote;
    IF done THEN
      LEAVE read_loop;
    END IF;

    SET v_mic = v_dealcount * v_dealquote * v_mkteffect * 0.01;

    INSERT INTO market_impact_cost_log (ordersmark, mic, calculated_at)
    VALUES (v_ordersmark, v_mic, CURRENT_TIMESTAMP);
  END LOOP;

  CLOSE cur;
END;
```

