CREATE TRIGGER generate_performance_alert_trigger
AFTER INSERT ON performance
FOR EACH ROW
BEGIN
  DECLARE @panel_id TEXT;
  DECLARE @plant_id TEXT;
  DECLARE @ppr REAL;
  DECLARE @expected_ppr REAL;
  DECLARE @panel_age_years REAL;
  DECLARE @rated_power INTEGER;
  DECLARE @current_efficiency REAL;
  DECLARE @replacement_priority TEXT;
  DECLARE @existing_alert_id TEXT;
  DECLARE @new_alert_id TEXT;
  DECLARE @alert_moment TEXT;

  SET @panel_id = NEW.solmodref;
  SET @alert_moment = NEW.perfmoment;

  SELECT panemark, powratew INTO @panel_id, @rated_power
  FROM panel
  WHERE panemark = @panel_id;

  SELECT hubregistry INTO @plant_id
  FROM panel
  WHERE panemark = @panel_id;

  SET @ppr = (NEW.measpoww / @rated_power) * 100;

  SET @expected_ppr = 100 - (0.7 * CAST((julianday(NEW.perfmoment) - julianday(
    SELECT initdate FROM plant WHERE growregistry = @plant_id
  )) / 365.25 AS REAL));

  IF @ppr < (@expected_ppr * 0.8) THEN
    SET @existing_alert_id = (
      SELECT alertreg
      FROM alerts
      WHERE deviceref = @panel_id
        AND alertstat = 'Critical'
        AND alertmoment > datetime(NEW.perfmoment, '-30 days')
      LIMIT 1
    );

    IF @existing_alert_id IS NOT NULL THEN
      UPDATE alerts
      SET alertcnt = COALESCE(alertcnt, 0) + 1
      WHERE alertreg = @existing_alert_id;
    ELSE
      SET @new_alert_id = 'ALERT_' || substr(hex(randomblob(8)), 1, 16);

      IF @ppr < (@expected_ppr * 0.6) THEN
        SET @replacement_priority = 'High';
      ELSE
        SET @replacement_priority = 'Medium';
      END IF;

      INSERT INTO alerts (
        alertreg,
        compreg,
        deviceref,
        incidentref,
        alertmoment,
        alertstat,
        alertcnt,
        maintprior,
        replaceprior,
        optpotential
      )
      VALUES (
        @new_alert_id,
        (SELECT growregistry FROM plant WHERE growregistry = @plant_id),
        @panel_id,
        NEW.perfregistry,
        @alert_moment,
        'Critical',
        1,
        'High',
        @replacement_priority,
        'High'
      );
    END IF;
  END IF;
END;
```

